def compute_crowd_penalties(prices, pool, params):
    close = prices['close']
    amount = prices['amount']
    n = len(pool)
    crowd_window = params["CrowdWindow"]
    thresholds = resolve_crowd_thresholds(params)
    ret_windows = resolve_crowd_ret_windows(params)
